import com.sun.net.httpserver.*;
import java.net.*;
import java.io.*;
import java.nio.charset.StandardCharsets;
import java.util.concurrent.*;

public class Stub {
    static volatile String body = "{\"price_cents\":3310,\"eta_hours\":41}";
    public static void main(String[] a) throws Exception {
        HttpServer s = HttpServer.create(new InetSocketAddress(9090), 0);
        s.setExecutor(Executors.newCachedThreadPool());
        PrintWriter log = new PrintWriter(new FileWriter("/tmp/stub/requests.log", true), true);
        s.createContext("/__set", ex -> {
            body = new String(ex.getRequestBody().readAllBytes(), StandardCharsets.UTF_8);
            send(ex, 200, "ok");
        });
        s.createContext("/v2/quote", ex -> {
            String q = ex.getRequestURI().getRawQuery();
            log.println(q);
            String zip = "";
            for (String p : q.split("&")) if (p.startsWith("zip=")) zip = p.substring(4);
            try {
                switch (zip) {
                    case "99999999" -> send(ex, 200, "{\"error\":\"ZIP_NOT_SERVED\"}");
                    case "88888888" -> { Thread.sleep(3000); send(ex, 200, body); }
                    case "55555555" -> { Thread.sleep(1500); send(ex, 200, body); }
                    case "77777777" -> send(ex, 500, "{\"error\":\"boom\"}");
                    case "66666666" -> send(ex, 200, "<html>oops</html>");
