                    case "33333333" -> send(ex, 200, "{\"error\":\"OTHER\"}");
                    default -> send(ex, 200, body);
                }
            } catch (Exception e) { }
        });
        s.start();
    }
    static void send(HttpExchange ex, int st, String b) throws IOException {
        byte[] bytes = b.getBytes(StandardCharsets.UTF_8);
        ex.getResponseHeaders().add("Content-Type", "application/json");
        ex.sendResponseHeaders(st, bytes.length);
        try (OutputStream o = ex.getResponseBody()) { o.write(bytes); }
    }
}
